function input(){if(returning||hudDrawerOpen||$('#help-dialog').open||$('#character-dialog').open)return {x:0,y:0};let key=[...keys].filter(k=>k!==' ').at(-1),order=keyboardOrder.get(key)||0;for(const held of touches.values())if(held.key&&held.order>=order){key=held.key;order=held.order;}return key==='d'||key==='arrowright'?{x:1,y:0}:key==='a'||key==='arrowleft'?{x:-1,y:0}:key==='w'||key==='arrowup'?{x:0,y:-1}:key==='s'||key==='arrowdown'?{x:0,y:1}:{x:0,y:0};}
