const accepted=['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'];document.addEventListener('keydown',e=>{if(returning||$('#help-dialog').open||$('#character-dialog').open)return;if(e.key==='Escape'&&hudDrawerOpen){setHudDrawer(false);return;}if(e.ctrlKey||e.metaKey||e.altKey)return;const key=e.key.toLowerCase();if(key==='escape'&&state.armed){state.armed=false;M.tell(state,'Spell cancelled.');return;}if(key==='p'||key==='escape'){if(!e.repeat)togglePause();return;}if(e.target.closest('input,select,textarea'))return;if((key==='f1'||key==='f2')&&!e.repeat&&ready&&!paused){e.preventDefault();M.pressPotion(state,key,key==='f1'?'life':'mana');return;}if(e.target.closest('button,a'))return;if(accepted.includes(key)){e.preventDefault();if(ready&&!paused&&!e.repeat){keys.delete(key);keys.add(key);keyboardOrder.set(key,++movementOrder);}}if(['1','2','3'].includes(key)&&!e.repeat&&ready&&!paused){e.preventDefault();selectSpell(['apocalipsis','inmovilizar','remover'][Number(key)-1]);prepareSpell();}if(key==='c'&&!e.repeat&&ready&&!paused){e.preventDefault();prepareSpell();}if(key===' '&&!e.repeat&&ready&&!paused){e.preventDefault();M.melee(state);}if(key==='q'&&!e.repeat&&ready&&!paused){if(!M.pickup(state,22))M.tell(state,'Stand on a dropped crystal, then press Q.');}if(key==='n'&&!e.repeat&&ready&&!paused){clear();M.meditate(state);}if(key==='u'&&!e.repeat&&ready&&!paused)useSelected();if(key==='e'&&!e.repeat&&ready&&!paused)interact();});document.addEventListener('keyup',e=>{const key=e.key.toLowerCase();keys.delete(key);keyboardOrder.delete(key);if(key==='f1'||key==='f2'){e.preventDefault();M.releasePotion(state,key);}});
